}

fn stamp(url: &str) -> u32 {
    let mut hash = 0x811c_9dc5_u32;
    for byte in url.bytes() {
        hash ^= u32::from(byte);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    hash
}

